import baseInfo from "./components/baseInfo";
import gridMenu from "./components/gridMenu";
import visitChart from "./components/visitChart";
import userChart from "./components/userChart";
import hotSearch from "./hot-search";
import userPreference from "./user-preference";
import { checkAuth } from "@/api/index";
import { auth } from "@/api/system";
import { Notice } from "iview";
import util from "@/libs/util";

export default {
  name: "index",
  components: {
    baseInfo,
    gridMenu,
    visitChart,
    userChart,
    hotSearch,
    userPreference,
  },
  data() {
    return {
      visitType: "day", // day, month, year
      visitDate: [new Date(), new Date()],
      openImage: false,
    };
  },
  mounted() {
    if (!util.cookies.get("auth")) {
      checkAuth()
        .then((res) => {})
        .catch((res) => {});
    }
    this.getAuth();
  },
  methods: {
    getAuth() {
      auth()
        .then((res) => {
          let data = res.data || {};
          if (data.auth_code && data.auth) {
            this.authCode = data.auth_code;
            this.auth = true;
          }
          this.openImage = true;
        })
        .catch((res) => {});
    },
    clear() {
      this.openImage = false;
    },
  },
};
